(function(){'use strict';const GAME='seven_up_down',HISTORY=100,BET_MS=15000;const token=(()=>{try{const h=new URLSearchParams(location.hash.replace(/^#/,'')).get('token');const q=new URLSearchParams(location.search).get('token');if(q){localStorage.setItem('ingames_token',q);return q}return h||window.IN_GAMES_AUTH_TOKEN||localStorage.getItem('ingames_token')}catch(_){return window.IN_GAMES_AUTH_TOKEN||null}})();const base=(window.IN_GAMES_SERVER_URL||'').replace(/\/$/,'');let round=null,status='BETTING_OPEN',closeAt=0,timer=null,history=[];const $=id=>document.getElementById(id);const headers=()=>({'Content-Type':'application/json',Accept:'application/json',...(token?{Authorization:`Bearer ${token}`}:{})});async function api(path,opt={}){const r=await fetch(base+path,{...opt,headers:{...headers(),...(opt.headers||{})}});let b=null;try{b=await r.json()}catch(_){}if(!r.ok)throw new Error(b?.message||b?.error?.message||`Request failed (${r.status})`);return b}function txt(id,v){const e=$(id);if(e)e.textContent=String(v)}function money(v){return `₹${Number(v||0).toFixed(2)}`}function type(sum){return sum===7?'SEVEN':sum>=8?'UP':'DOWN'}function statusText(v){let e=$('liveGameStatus');if(!e){e=document.createElement('div');e.id='liveGameStatus';e.style.cssText='position:fixed;left:50%;top:76px;transform:translateX(-50%);z-index:1000;padding:6px 12px;border-radius:999px;background:rgba(20,8,48,.86);color:#fff;font:600 11px Poppins,sans-serif;pointer-events:none;';document.body.appendChild(e)}e.textContent=v}function timerTick(){const left=Math.max(0,closeAt-Date.now()),sec=Math.ceil(left/1000),p=$('timerProgress'),c=2*Math.PI*30;txt('timerText',status==='BETTING_OPEN'?sec:'🎲');if(p){p.style.strokeDasharray=c;p.style.strokeDashoffset=c*(1-Math.min(1,left/BET_MS))}['btnBetDown','btnBetSeven','btnBetUp'].forEach(id=>{const e=$(id);if(e)e.classList.toggle('disabled',status!=='BETTING_OPEN'||left<=0)});if(left<=0&&status==='BETTING_OPEN'){status='BETTING_CLOSED';statusText('Betting Closed')}}function renderHistory(){const r=$('historyRibbon');if(!r)return;r.innerHTML='';history.slice(0,HISTORY).forEach(x=>{const n=Number(x.diceSum??x.sum??x.total);if(!n)return;const e=document.createElement('div');e.className=`badge-num ${n===7?'badge-blue':n<7?'badge-red':'badge-green'}`;e.textContent=n;e.title=`Round ${x.roundNumber||x.roundId||''}: ${x.dice1||'?'} + ${x.dice2||'?'} = ${n}`;r.appendChild(e)})}function addHistory(x){if(!x||!Number.isFinite(Number(x.diceSum))||history.some(h=>h.roundId===x.roundId))return;history.unshift(x);history=history.slice(0,HISTORY);renderHistory()}function dice(a,b){if($('dice1'))$('dice1').textContent=a??'?';if($('dice2'))$('dice2').textContent=b??'?'}function apply(r,remaining){if(!r)return;round=r;status=r.status||'BETTING_OPEN';closeAt=Date.now()+Math.max(0,Number.isFinite(Number(remaining))?Number(remaining):BET_MS);if(r.dice1!=null)dice(r.dice1,r.dice2);if(r.status==='SETTLED')addHistory(r);statusText(`Round ${r.roundNumber||''} • ${status==='BETTING_OPEN'?'Betting Open':status}`);if(timer)clearInterval(timer);timer=setInterval(timerTick,100);timerTick()}async function sync(){try{const b=await api('/api/games/7updown/current-round');if(b?.status==='success'){apply(b.data?.currentRound||b.data,b.data?.timeRemainingMs)}}catch(e){statusText(e.message.includes('401')?'Game session expired':'Reconnecting…')}}async function loadHistory(){try{const b=await api(`/api/games/7updown/history?limit=${HISTORY}`);if(b?.status==='success'&&Array.isArray(b.data)){history=b.data.slice(0,HISTORY);renderHistory()}}catch(_){}}function resetBets(){window.__SUD_BETS={DOWN:0,SEVEN:0,UP:0};window.__SUD_TOTAL=0;txt('badgeDown',money(0));txt('badgeSeven',money(0));txt('badgeUp',money(0));txt('totalTableBetVal',money(0))}function open(e){round=e?.roundId||null;status='BETTING_OPEN';closeAt=Date.now()+Number(e?.bettingDurationSeconds||15)*1000;resetBets();statusText('Betting Open')}function result(e){if(!e)return;status='RESULT';dice(e.dice1,e.dice2);window.__SUD_LAST={roundId:e.roundId||round,dice1:e.dice1,dice2:e.dice2,diceSum:e.diceSum??e.sum,winningBetType:e.winningBetType};statusText(`${e.dice1} + ${e.dice2} = ${e.diceSum??e.sum} • ${e.winningBetType||type(e.diceSum??e.sum)}`)}function settled(){status='SETTLED';if(window.__SUD_LAST)addHistory(window.__SUD_LAST);resetBets();statusText('Round Settled');window.parent?.postMessage?.({source:'ingames-game',version:1,type:'ROUND_RESULT',roundId:round},'*')}async function bet(kind){if(status!=='BETTING_OPEN'||Date.now()>=closeAt)return statusText('Betting closed');if(!round){await sync();if(!round)return}const amount=Number(window.__SUD_SELECTED_CHIP||10);try{const id=`${round}:${kind}:${Date.now()}:${Math.random().toString(36).slice(2)}`;const b=await api('/api/games/7updown/bets',{method:'POST',body:JSON.stringify({roundId:round,bets:[{betType:kind,stake:amount,idempotencyKey:id}]})});if(b?.status!=='success')throw new Error(b?.message||'Bet rejected');window.__SUD_BETS[kind]+=amount;window.__SUD_TOTAL+=amount;txt(kind==='DOWN'?'badgeDown':kind==='SEVEN'?'badgeSeven':'badgeUp',money(window.__SUD_BETS[kind]));txt('totalTableBetVal',money(window.__SUD_TOTAL));statusText(`${kind} • ${money(amount)} accepted`);window.parent?.postMessage?.({source:'ingames-game',version:1,type:'WALLET_UPDATED',balance:b.data?.wallet?.totalBalance??b.data?.wallet?.cashBalance},'*')}catch(e){statusText(e.message||'Bet rejected')}}function socket(){if(typeof window.io!=='function')return statusText('Live connection unavailable');const s=window.io(base||undefined,{auth:token?{token}:{} ,transports:['websocket','polling'],reconnection:true,reconnectionAttempts:Infinity,reconnectionDelay:500});s.on('connect',()=>{statusText('Live • Connected');sync();loadHistory()});s.on('disconnect',()=>statusText('Live • Reconnecting…'));s.on('7ud:round_open',open);s.on('GAME_ROUND_OPEN',e=>open(e?.payload||e));s.on('7ud:dice_rolled',result);s.on('GAME_RESULT',e=>result(e?.payload||e));s.on('7ud:round_settled',settled);s.on('GAME_ROUND_SETTLED',settled);return s}function bind(){window.__SUD_SELECTED_CHIP=10;window.__SUD_BETS={DOWN:0,SEVEN:0,UP:0};window.__SUD_TOTAL=0;const map={btnBetDown:'DOWN',btnBetSeven:'SEVEN',btnBetUp:'UP'};document.addEventListener('click',e=>{const t=e.target instanceof Element?e.target.closest('[id]'):null;if(!t||!map[t.id])return;e.preventDefault();e.stopImmediatePropagation();bet(map[t.id])},true);document.addEventListener('click',e=>{const c=e.target instanceof Element?e.target.closest('.pop-chip[data-val]'):null;if(!c)return;const v=Number(c.dataset.val);if(v>0){window.__SUD_SELECTED_CHIP=v;const p=$('chipRadialPopup');if(p)p.classList.remove('active','show');statusText(`Chip selected • ${money(v)}`)}},true);const settings=$('btnSettings'),modal=$('settingsModal'),close=$('btnCloseSettings');if(settings&&modal)settings.addEventListener('click',()=>modal.classList.add('active'));if(close&&modal)close.addEventListener('click',()=>modal.classList.remove('active'));if(modal)modal.addEventListener('click',e=>{if(e.target===modal)modal.classList.remove('active')});loadHistory();sync();socket();setInterval(sync,5000)}if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',bind,{once:true});else bind();})();